Method.Implementation:
 try{
		 do ##super()
		 $$$TRACE("Connect to " _ ..ApplicationAddress)
		 $$$TRACE("Connect to " _ ..TuxedoService)
		 set ..objCdrTuxService = ##class(org.ihc.itf.cdr.drc.InitiateContextAndCdrTaskSearch).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService, ..LogDirectory _"/" _$$$JobConfigName _".log", $$$ConfigTrace($$$JobConfigName))
     	 set status = ..CheckObject()
	}catch err{
		 $$$LOGERROR("Exception while Creating Tuxedo Service: " _err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
	     Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName," Exception while initializing Tuxedo Service: "_err.AsSystemError()_"::"_err.Data_"::"_err.Code)
	}	
	quit status
